from fastapi import APIRouter, Depends, HTTPException
from temporalio.client import Client

router = APIRouter(prefix="/mortgages/workflows")

@router.get("/{workflow_id}/underwriting-summary")
async def query_underwriting_summary(
    workflow_id: str,
    temporal_client: Client = Depends(get_temporal_client),
    user: LoanUser = Depends(get_loan_user),
    mortgage_repo: MortgageRepository = Depends(get_mortgage_repo)
):
    application = await mortgage_repo.find_by_workflow_id(workflow_id)
    if not application:
        raise HTTPException(status_code=404, detail="Mortgage application not found")
    if application.user_id != user.id and not user.is_underwriter:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to query this loan workflow")

    try:
        handle = temporal_client.get_workflow_handle(workflow_id)
        summary = await handle.query("get_risk_evaluation")
        return {"workflow_id": workflow_id, "evaluation": summary}
    except Exception as e:
        raise HTTPException(status_code=404, detail="Workflow instance not found or terminated")
